def select_point(curve):
    if not curve or len({p['epoch'] for p in curve}) != len(curve):
        raise ValueError('Missing or duplicated complete-Dev snapshots')
    return min(curve, key=lambda p: (-p['HOTA'], p['epoch']))


def common_budget_decision(curves, epoch):
    if epoch not in [18, 24, 30, 36] or len(curves) != 16:
        raise ValueError('All16 complete matched backend curves are required')
    expected = list(range(6, epoch + 1, 6))
    gains = {}
    for key, curve in curves.items():
        if sorted(p['epoch'] for p in curve) != expected:
            raise ValueError('No stopping on partial/missing Dev curves')
        recent = max(p['HOTA'] for p in curve)
        earlier = max(p['HOTA'] for p in curve if p['epoch'] <= epoch - 12)
        gains[key] = recent - earlier
    extend = epoch < 36 and any(value > .2 + 1e-10 for value in gains.values())
    return dict(common_epochs=epoch, extend_all8_heads=extend, next_epochs=epoch + 6 if extend else epoch,
                gains_vs_best_through12_epochs_earlier=gains, Test_read=False,
                rule='Any of16 complete matched Dev curves gains>0.2pp over its best through12epochs earlier; cap36.')


def selected_cases(study, curves):
    """Freeze all normal/control/removal cases before evaluating any new Test."""
    heads = {head['id']: head for head in study['heads']}
    cases, roles, by_identity = {}, {}, {}

    def add(role, case):
        identity = config_identity(case['config'])
        if identity in by_identity:
            roles[role] = by_identity[identity]
        else:
            assert case['id'] not in cases
            cases[case['id']] = case; by_identity[identity] = case['id']; roles[role] = case['id']
        return roles[role]

    for head in study['heads']:
        for algorithm in ALGORITHMS:
            choice = select_point(curves[head['id'] + '_' + algorithm])
            for intervention in ['normal', 'missing'] + (['feature_mismatch'] if head['cue'] == 'ir' else []):
                role = head['id'] + '_' + algorithm + '_' + intervention
                add(role, config_for(study, head, choice['epoch'], algorithm, intervention))
    primary = study['primary']
    primary_head = heads[primary['head']]
    algorithm = primary['algorithm']
    epoch = select_point(curves[primary_head['id'] + '_' + algorithm])['epoch']
    roles['primary'] = roles[primary_head['id'] + '_' + algorithm + '_normal']
    for name in ['no_alignment', 'no_null', 'no_prebirth', 'no_covisible', 'no_object_files', 'no_consensus']:
        add('primary_' + name, config_for(study, primary_head, epoch, algorithm, name))
    for kind, cue, role in [('clean', 'ir', 'primary_paired_no_KL'),
                            ('robust', 'rgb', 'primary_paired_extra_RGB')]:
        head = heads[head_id(kind, primary_head['frontend'], cue)]
        add(role, config_for(study, head, epoch, algorithm))
    for case in baselines():
        add(case['id'], case)
    return dict(cases=list(cases.values()), roles=roles,
                primary_snapshot=epoch, original16_complete_Dev_selections={
                    key: select_point(curve) for key, curve in curves.items()},
                Test_accuracy_read_for_selection=False)

def select_complete_dev(rows, through_epoch, primary_epoch, mode):
    """Preserve the parent's primary and budget; select no primary from Test."""
    if through_epoch not in [6, 9, 12] or not 1 <= primary_epoch <= through_epoch:
        raise ValueError('Use the already frozen parent budget and primary epoch')
    if mode not in ['quality', 'temporal']:
        raise ValueError('Use the frozen parent primary mode')
    expected = {(cell, epoch) for cell in CELLS for epoch in range(1, through_epoch+1)}
    found = {}
    lineage = set()
    for row in rows:
        key = row['cell'], row['epoch']
        if (key not in expected or key in found or row['split'] != 'dev' or
                row['sequences'] != DEV_SEQUENCES or row['frames'] != 4834 or
                row['seed'] != 0 or row['cue'] != 'ir' or row['mode'] != mode or
                row.get('intervention', 'normal') != 'normal' or
                row['executed_fit_budget'] != through_epoch):
            raise ValueError('Need complete matched, normal seed0 Dev curves for all four cells')
        if any(not math.isfinite(float(row['metrics'][k])) for k in ['HOTA', 'AssA', 'IDF1']):
            raise ValueError('Nonfinite official Dev metrics')
        if row['complete_Train_frames_per_epoch'] != 27251:
            raise ValueError('A sampled Train subset cannot supply a matched factorial cell')
        lineage.add((row['source_RGB_sha256'], row['initial_native_sha256'],
                     row['Train_schedule_sha256']))
        found[key] = row
    if set(found) != expected or len(lineage) != 1:
        raise ValueError('Missing cells/epochs or unequal source, initialization or Train schedule')
    paired = {cell: found[cell, primary_epoch] for cell in CELLS}
    own = {cell: best_dev([found[cell, epoch] for epoch in range(1, through_epoch+1)]) for cell in CELLS}
    return dict(paired_parent_primary_epoch=paired, own_Dev_best=own,
        fixed_parent_primary_mode=mode, fixed_parent_primary_epoch=primary_epoch,
        executed_complete_Train_epochs_each=through_epoch,
        Test_used_for_selection=False, every_selected_cell_requires_full_Test=True)

def best_dev(rows):
    rows=list(rows)
    if not rows:raise ValueError('No complete normal Dev candidate')
    indexed_dev(rows)
    if any(r['intervention']!='normal' for r in rows):raise ValueError('Interventions cannot choose a normal model')
    return max(rows,key=lambda r:(float(r['selection_metrics']['HOTA']),float(r['selection_metrics']['AssA']),
        float(r['selection_metrics']['IDF1']),-r['epoch'],-VARIANTS.index(r['variant']),-CUES.index(r['cue'])))


def own_best(rows,through):
    normal=complete_curves(rows,through)
    return {(v,c):best_dev(r for (variant,cue,_,_),r in normal.items() if (variant,cue)==(v,c)) for v,c in NORMAL}


def budget_decision(rows,stage):
    if stage not in (6,9,12):raise ValueError('Only common complete-Train stages 6,9,12')
    current=own_best(rows,stage);complete_interventions(rows,stage)
    if stage==12:return dict(stage=stage,extend_all=False,through_epoch=12,reason='fixed_maximum_complete_Train_budget')
    previous=own_best(rows,stage-3)
    improved=[]
    for key in NORMAL:
        new=Decimal(str(current[key]['selection_metrics']['HOTA']))
        old=Decimal(str(previous[key]['selection_metrics']['HOTA']))
        if new-old>Decimal('0.2'):improved.append(dict(variant=key[0],cue=key[1],absolute_HOTA_gain=str(new-old)))
    extend=bool(improved)
    return dict(stage=stage,extend_all=extend,through_epoch=stage+3 if extend else stage,
        improved_conditions=improved,reason='complete_Dev_common_budget_rule',learning_rate_horizon_complete_Train_epochs=12)


def select_models(rows,through):
    if through not in (6,9,12):raise ValueError('Normal selection requires an executed complete common stage')
    own=own_best(rows,through);complete_interventions(rows,through)
    primary=best_dev(own[v,'ir'] for v in VARIANTS)
    return dict(through_epoch=through,primary=primary,
        normal_models=[own[key] for key in NORMAL],
        matched_RGB=own[primary['variant'],'rgb'],matched_gray=own[primary['variant'],'gray'],
        strongest_Dev_RGB=best_dev(own[v,'rgb'] for v in VARIANTS),
        strongest_Dev_gray=best_dev(own[v,'gray'] for v in VARIANTS),
        decision_split='dev',all_twelve_formal_models_require_complete_Test=True)
